use project_ledger_canonical_json::sha256_bytes;
use project_ledger_domain::{
    CheckpointFreshnessStatus, EventEnvelope, EvidenceStatus, GeneratedArtifactKind,
    GeneratedArtifactRecord, LedgerTimestamp, ResourceRef, StableId,
};
use project_ledger_projection_engine::ProjectStateProjection;
use serde::Serialize;
use thiserror::Error;

const GENERATED_WARNING: &str =
    "<!-- GENERATED BY PROJECT LEDGER. DO NOT EDIT AS CANONICAL STATE. -->";

/// Privacy policy applied to the deterministic Markdown projection.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum RendererPrivacyProfile {
    FullLocal,
    MinimalLocal,
    Shareable,
}

impl RendererPrivacyProfile {
    pub const fn as_str(self) -> &'static str {
        match self {
            Self::FullLocal => "FULL_LOCAL",
            Self::MinimalLocal => "MINIMAL_LOCAL",
            Self::Shareable => "SHAREABLE",
        }
    }
}

/// Stable parameters that identify a generated Markdown artifact.
#[derive(Clone, Debug, PartialEq)]
pub struct MarkdownRenderRequest {
    pub artifact_id: StableId,
    pub uri: ResourceRef,
    pub renderer_version: String,
    pub privacy_profile: RendererPrivacyProfile,
    pub created_at: LedgerTimestamp,
}

/// In-memory bytes plus the audit record needed to verify them later.
#[derive(Clone, Debug, PartialEq)]
pub struct RenderedMarkdown {
    pub content: String,
    pub record: GeneratedArtifactRecord,
}

#[derive(Debug, Error)]
pub enum MarkdownRenderError {
    #[error("renderer_version cannot be empty")]
    EmptyRendererVersion,
    #[error("the supplied event stream does not match the projection")]
    StreamProjectionMismatch,
}

/// Pure renderer for the replaceable human status view.
#[derive(Debug)]
pub struct MarkdownRenderer;

impl MarkdownRenderer {
    /// Renders the frozen 13-section view without mutating canonical state.
    ///
    /// # Errors
    ///
    /// Fails when the renderer version is empty or the source stream and
    /// projection do not identify the same canonical head.
    pub fn render(
        projection: &ProjectStateProjection,
        stream: &[EventEnvelope],
        request: &MarkdownRenderRequest,
    ) -> Result<RenderedMarkdown, MarkdownRenderError> {
        if request.renderer_version.trim().is_empty() {
            return Err(MarkdownRenderError::EmptyRendererVersion);
        }
        let state = projection.state();
        if stream.last().is_none_or(|head| {
            head.stream_version != state.state_version
                || head.event_digest != projection.head_digest()
        }) {
            return Err(MarkdownRenderError::StreamProjectionMismatch);
        }

        let content = render_content(projection, stream, request.privacy_profile);
        let record = GeneratedArtifactRecord {
            schema_version: state.schema_version,
            generated_artifact_id: request.artifact_id.clone(),
            kind: GeneratedArtifactKind::Markdown,
            uri: request.uri.clone(),
            source_state_version: state.state_version,
            source_state_digest: state.state_digest,
            renderer_version: request.renderer_version.clone(),
            privacy_profile: request.privacy_profile.as_str().to_owned(),
            artifact_digest: sha256_bytes(content.as_bytes()),
            created_at: request.created_at.clone(),
        };
        Ok(RenderedMarkdown { content, record })
    }
}

#[allow(clippy::too_many_lines)] // The frozen 13-section order stays linear for audit review.
fn render_content(
    projection: &ProjectStateProjection,
    stream: &[EventEnvelope],
    profile: RendererPrivacyProfile,
) -> String {
    let state = projection.state();
    let mut output = String::new();
    line(&mut output, GENERATED_WARNING);
    line(&mut output, "");
    if profile == RendererPrivacyProfile::Shareable {
        line(&mut output, "# Estado del proyecto");
    } else {
        line(
            &mut output,
            &format!("# {}", bounded_text(&state.project.title, 120)),
        );
    }

    section(&mut output, "## 1. Estado ejecutivo");
    bullet(&mut output, "Proyecto", state.project.project_id.as_str());
    bullet(
        &mut output,
        "Estado",
        &enum_name(&state.project.lifecycle_status),
    );
    bullet(
        &mut output,
        "Versión canónica",
        &state.state_version.to_string(),
    );
    bullet(
        &mut output,
        "Versión material",
        &state.material_state_version.to_string(),
    );
    if profile == RendererPrivacyProfile::FullLocal {
        bullet(
            &mut output,
            "Resumen",
            &bounded_text(&state.project.summary, 240),
        );
    }

    section(&mut output, "## 2. Autoridad y documentos vigentes");
    if state.authority_documents.is_empty() {
        empty(&mut output);
    }
    for document in &state.authority_documents {
        let mut value = format!(
            "{} | {} | {}",
            document.document_id,
            enum_name(&document.status),
            document.digest
        );
        if profile == RendererPrivacyProfile::FullLocal {
            write!(value, " | {}", document.uri).expect("writing to String cannot fail");
        }
        line(&mut output, &format!("- {value}"));
    }

    section(&mut output, "## 3. Fase activa y roadmap");
    bullet(
        &mut output,
        "Roadmap",
        &state.roadmap.as_ref().map_or_else(
            || "ninguno".to_owned(),
            |roadmap| {
                if profile == RendererPrivacyProfile::Shareable {
                    roadmap.roadmap_id.to_string()
                } else {
                    format!(
                        "{} ({})",
                        roadmap.roadmap_id,
                        bounded_text(&roadmap.title, 120)
                    )
                }
            },
        ),
    );
    refs(&mut output, "Fases activas", &state.active_phase_refs);
    refs(
        &mut output,
        "Fases completadas",
        &state.completed_phase_refs,
    );

    section(&mut output, "## 4. Gates");
    refs(&mut output, "Pendientes", &state.pending_gate_refs);
    refs(&mut output, "Verificados", &state.verified_gate_refs);
    refs(
        &mut output,
        "Revalidación requerida",
        &state.revalidation_required_gate_refs,
    );

    section(&mut output, "## 5. Últimos avances materiales");
    if let Some(work) = projection.latest_work_record() {
        bullet(&mut output, "Registro", work.work_record_id.as_str());
        if profile != RendererPrivacyProfile::Shareable {
            bullet(&mut output, "Resumen", &bounded_text(&work.summary, 240));
        }
        if profile == RendererPrivacyProfile::FullLocal {
            bullet(&mut output, "Actor", work.actor_ref.as_str());
            let artifacts: Vec<_> = work
                .files_or_artifacts
                .iter()
                .map(ToString::to_string)
                .collect();
            bullet(&mut output, "Archivos o artefactos", &joined(&artifacts));
        }
    } else {
        empty(&mut output);
    }

    section(&mut output, "## 6. Evidencia verificada");
    let verified: Vec<_> = projection
        .evidence_records()
        .into_iter()
        .filter(|evidence| evidence.status == EvidenceStatus::VerifiedSource)
        .collect();
    if verified.is_empty() {
        empty(&mut output);
    }
    for evidence in verified {
        line(
            &mut output,
            &format!(
                "- {} | {} | {}",
                evidence.evidence_id,
                enum_name(&evidence.kind),
                enum_name(&evidence.status)
            ),
        );
    }

    section(&mut output, "## 7. Decisiones vigentes");
    if state.current_decision_refs.is_empty() {
        empty(&mut output);
    }
    for decision_ref in &state.current_decision_refs {
        let detail = projection.decision(decision_ref).map_or_else(
            || decision_ref.to_string(),
            |decision| {
                if profile == RendererPrivacyProfile::Shareable {
                    format!("{} | {}", decision.decision_id, enum_name(&decision.status))
                } else {
                    format!(
                        "{} | {} | {}",
                        decision.decision_id,
                        enum_name(&decision.status),
                        bounded_text(&decision.title, 120)
                    )
                }
            },
        );
        line(&mut output, &format!("- {detail}"));
    }

    section(&mut output, "## 8. Blockers y riesgos");
    refs(&mut output, "Blockers abiertos", &state.open_blocker_refs);
    refs(&mut output, "Riesgos abiertos", &state.open_risk_refs);

    section(&mut output, "## 9. Próximas acciones");
    refs(
        &mut output,
        "Acción preferida",
        &state
            .preferred_next_action_ref
            .iter()
            .cloned()
            .collect::<Vec<_>>(),
    );
    refs(&mut output, "Ordenadas", &state.ordered_next_action_refs);

    section(&mut output, "## 10. Checkpoint de continuidad");
    if let Some(checkpoint_ref) = &state.checkpoint_ref {
        bullet(&mut output, "Checkpoint", checkpoint_ref.as_str());
        let freshness = projection
            .checkpoint_freshness(checkpoint_ref)
            .unwrap_or(CheckpointFreshnessStatus::Unknown);
        bullet(&mut output, "Frescura", &enum_name(&freshness));
        if let Some(checkpoint) = projection.checkpoint(checkpoint_ref) {
            bullet(
                &mut output,
                "Estado capturado",
                &checkpoint.captured_state_version.to_string(),
            );
        }
    } else {
        empty(&mut output);
    }

    section(&mut output, "## 11. Timeline reciente");
    for event in stream
        .iter()
        .rev()
        .take(10)
        .collect::<Vec<_>>()
        .into_iter()
        .rev()
    {
        let mut detail = format!(
            "{} | {} | {}",
            event.stream_version,
            enum_name(&event.event_type()),
            event.event_id
        );
        if profile == RendererPrivacyProfile::FullLocal {
            write!(
                detail,
                " | {} | {}",
                event.recorded_at, event.actor.actor_id
            )
            .expect("writing to String cannot fail");
        }
        line(&mut output, &format!("- {detail}"));
    }

    section(&mut output, "## 12. Conflictos y unknowns");
    refs(
        &mut output,
        "Conflictos abiertos",
        &state.open_conflict_refs,
    );
    let unknown_refs = projection.open_unknown_refs();
    refs(&mut output, "Unknowns abiertos", &unknown_refs);
    if profile == RendererPrivacyProfile::FullLocal {
        for unknown_ref in &unknown_refs {
            if let Some(unknown) = projection.unknown(unknown_ref) {
                line(
                    &mut output,
                    &format!(
                        "  - {} | {} | {}",
                        unknown.unknown_id,
                        enum_name(&unknown.criticality),
                        bounded_text(&unknown.statement, 200)
                    ),
                );
            }
        }
    }

    section(&mut output, "## 13. Apéndice histórico resumido");
    bullet(&mut output, "Eventos canónicos", &stream.len().to_string());
    bullet(
        &mut output,
        "Digest de estado",
        &state.state_digest.to_string(),
    );
    bullet(&mut output, "Perfil de privacidad", profile.as_str());
    output
}

fn enum_name<T: Serialize>(value: &T) -> String {
    serde_json::to_string(value)
        .expect("closed contract enums always serialize")
        .trim_matches('"')
        .to_owned()
}

fn section(output: &mut String, title: &str) {
    line(output, "");
    line(output, title);
    line(output, "");
}

fn line(output: &mut String, value: &str) {
    output.push_str(value);
    output.push('\n');
}

fn bullet(output: &mut String, label: &str, value: &str) {
    line(output, &format!("- {label}: {value}"));
}

fn refs(output: &mut String, label: &str, values: &[StableId]) {
    let values: Vec<_> = values.iter().map(ToString::to_string).collect();
    bullet(output, label, &joined(&values));
}

fn joined(values: &[String]) -> String {
    if values.is_empty() {
        "ninguno".to_owned()
    } else {
        values.join(", ")
    }
}

fn bounded_text(value: &str, maximum_characters: usize) -> String {
    let normalized = value
        .split_whitespace()
        .map(redact_secret_word)
        .collect::<Vec<_>>()
        .join(" ");
    if normalized.chars().count() <= maximum_characters {
        return normalized;
    }
    let retained = maximum_characters.saturating_sub(1);
    let mut bounded = normalized.chars().take(retained).collect::<String>();
    bounded.push('…');
    bounded
}

fn redact_secret_word(word: &str) -> String {
    let lower = word.to_ascii_lowercase();
    for prefix in [
        "api_key=",
        "apikey=",
        "access_token=",
        "token=",
        "secret=",
        "password=",
    ] {
        if lower.starts_with(prefix) {
            return format!("{}[REDACTED]", &word[..prefix.len()]);
        }
    }
    word.to_owned()
}

fn empty(output: &mut String) {
    line(output, "- Sin registros.");
}
use std::fmt::Write as _;
